package edu.focuslock

import java.security.MessageDigest
import javax.crypto.Mac
import javax.crypto.spec.SecretKeySpec

/**
 * Pure signing functions with no Android or OkHttp types, so they can be unit tested on the JVM
 * against backend/test_vectors.json (generated by the Python server's sign()).
 *
 * Sig = HMAC-SHA256(secret, METHOD \n path_with_query \n ts \n nonce \n sha256_hex(body))
 * Do not change this format: the server verifies it byte for byte.
 */
object Signer {

    fun sign(secretHex: String, method: String, pathWithQuery: String, ts: String, nonce: String, body: ByteArray): String {
        val msg = listOf(method.uppercase(), pathWithQuery, ts, nonce, sha256Hex(body)).joinToString("\n")
        return hmacHex(secretHex, msg)
    }

    /** Check-in proof that the request comes from the enrolled device (mirrors main.device_sig). */
    fun deviceSig(deviceKeyHex: String, sessionId: String, studentId: String, code: String, ts: String): String =
        hmacHex(deviceKeyHex, listOf("checkin", sessionId, studentId, code, ts).joinToString("\n"))

    fun sha256Hex(data: ByteArray): String = MessageDigest.getInstance("SHA-256").digest(data).toHex()

    private fun hmacHex(keyHex: String, msg: String): String {
        val mac = Mac.getInstance("HmacSHA256")
        mac.init(SecretKeySpec(hexToBytes(keyHex), "HmacSHA256"))
        return mac.doFinal(msg.toByteArray(Charsets.UTF_8)).toHex()
    }

    fun hexToBytes(hex: String): ByteArray {
        require(hex.length % 2 == 0) { "hex string must have even length" }
        return ByteArray(hex.length / 2) { i -> hex.substring(2 * i, 2 * i + 2).toInt(16).toByte() }
    }

    private fun ByteArray.toHex(): String = joinToString("") { "%02x".format(it.toInt() and 0xff) }
}
